type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string = ""
var WsBalEd string = ""
var WsTotEd string = ""

var ledgerFile *os.File
var ledgerReader *bufio.Reader
var ledgerRec LedgerRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func formatInt(value int64, digits int) string {
	s := fmt.Sprintf("%d", value)
	if s[0] == '-' {
		s = s[1:]
	}
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return fmt.Sprintf("%0*d", digits, mustAtoi(s))
}
func mustAtoi(s string) int64 {
	var n int64
	for _, c := range s {
		n = n*10 + int64(c-'0')
	}
	return n
}

func formatEdited(pic string, val decimal.Decimal) string {
	// Determine sign placeholder
	hasSign := len(pic) > 0 && pic[0] == '-'
	signChar := ' '
	isNeg := val.IsNegative()
	if isNeg {
		signChar = '-'
		val = val.Neg()
	}
	// Find decimal point
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[dotIdx+1:]
		// Actually intPic is before dot, frac after
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	if hasSign {
		intPic = intPic[1:] // remove leading '-'
	}
	fracDigits := len(fracPic) // number of 9's after dot

	// Count integer digit placeholders
	intDigitCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitCount++
		}
	}

	// Get integer and fractional parts
	// val has at most 2 decimal places; we need to extract absolute value
	// Use truncation toward zero (val is positive here)
	// Get integer part
	intPart := val.Truncate(0)
	// For fractional, get 10^fracDigits * fractional part
	// Use val - intPart
	fracPart := val.Sub(intPart).Abs()
	// To avoid decimal issues, use Shift
	// frac as integer
	var fracInt int64
	if fracDigits > 0 {
		shifted := fracPart.Shift(int32(fracDigits))
		// truncate
		shifted = shifted.Truncate(0)
		fracInt = shifted.IntPart()
	}

	// Overflow handling: drop high-order digits
	// compute 10^intDigitCount
	mod := int64(1)
	for i := 0; i < intDigitCount; i++ {
		mod *= 10
	}
	intVal := intPart.IntPart()
	if intDigitCount > 0 && mod > 1 {
		// handle larger than 64-bit potential? intDigitCount max 7, mod fits
		intVal = intVal % mod
	}

	// Build integer digits string zero-padded to intDigitCount
	intDigitsStr := fmt.Sprintf("%0*d", intDigitCount, intVal)
	if intDigitCount == 0 {
		intDigitsStr = ""
	}

	// Build integer formatted section including commas
	// Map digits onto intPic placeholders
	var intFormatted []rune
	digitIdx := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intFormatted = append(intFormatted, rune(intDigitsStr[digitIdx]))
			digitIdx++
		} else {
			intFormatted = append(intFormatted, c) // ',' etc
		}
	}

	// Apply Z suppression: leading zeros become spaces
	// Find position of last digit that is significant
	// A digit is significant if it is non-zero, or if any less-significant digit position is a '9' required?
	// Standard: Z suppression: leading zeros up to the last Z before a non-zero digit are suppressed.
	// Implementation: scan digits from left; keep suppressed = true until we encounter a non-zero digit.
	// Once we hit non-zero, suppression ends. However a '9' position forces display even if zero? Actually '9' always prints digit, so it ends suppression.
	// Simpler: determine first index where suppression stops.
	// Build array of placeholder types for intFormatted align.
	// For each position in intFormatted, if it's digit placeholder, check suppression.
	suppressing := true
	// Need to know for each digit placeholder whether it's Z or 9
	placeholderTypes := []rune{}
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			placeholderTypes = append(placeholderTypes, c)
		}
	}
	// We'll iterate over intFormatted and placeholder index
	phIdx := 0
	for i, ch := range intFormatted {
		if ch >= '0' && ch <= '9' {
			pt := placeholderTypes[phIdx]
			if suppressing {
				if pt == '9' {
					// 9 always prints, even zero, so suppression ends before this
					// But if digit is zero, it prints '0' and suppression ends
					suppressing = false
				} else { // Z
					if ch == '0' {
						// check if there is any non-zero digit later before end?
						// If all remaining digits are zero, we still keep last digit? Actually last Z before decimal with all zeros should show 0? In COBOL, ZZ,ZZ9.99 with zero would show "        0.00" - the 9 ensures a zero.
						// Since we have at least one '9' at the end, the final '9' will be kept.
						// So suppress this zero
						intFormatted[i] = ' '
						phIdx++
						continue
					} else {
						suppressing = false
					}
				}
			}
			phIdx++
		}
	}
	// Commas inside suppressed zone become spaces
	// A comma is suppressed if all digit positions to its left are suppressed (i.e., are spaces) and all digit positions to its right up to next significant digit are still suppressed? Simpler: if every digit to the left of comma is space (suppressed), then comma becomes space.
	// Implement: for each comma position, check if any non-space digit appears to its left in intFormatted; if not, make it space. Also if suppression still active to the right, but left check suffices because commas between suppressed digits will have no non-space left.
	for i, ch := range intFormatted {
		if ch == ',' {
			hasNonSpaceLeft := false
			for j := 0; j < i; j++ {
				if intFormatted[j] != ' ' && intFormatted[j] != ',' {
					hasNonSpaceLeft = true
					break
				}
				// Actually digits that are spaces indicate suppressed; commas already maybe spaces
				if intFormatted[j] != ' ' && intFormatted[j] != ',' {
					hasNonSpaceLeft = true
				}
			}
			// Check left for any digit that is not space
			for j := 0; j < i; j++ {
				if intFormatted[j] >= '0' && intFormatted[j] <= '9' {
					hasNonSpaceLeft = true
					break
				}
			}
			if !hasNonSpaceLeft {
				intFormatted[i] = ' '
			}
		}
	}

	// Build final string
	var result string
	if hasSign {
		result = string(signChar)
	}
	result += string(intFormatted)
	if fracDigits > 0 {
		result += "."
		fracStr := fmt.Sprintf("%0*d", fracDigits, fracInt)
		if len(fracStr) > fracDigits {
			fracStr = fracStr[len(fracStr)-fracDigits:]
		}
		result += fracStr
	}
	// Ensure length equals pic length (for safety pad left with spaces if needed due to sign handling)
	// pic length includes sign
	if len(result) < len(pic) {
		result = strings.Repeat(" ", len(pic)-len(result)) + result
	} else if len(result) > len(pic) {
		result = result[len(result)-len(pic):]
	}
	return result
}

func moveToWsAmtEd(v decimal.Decimal) {
	WsAmtEd = formatEdited("ZZ,ZZ9.99", v)
}
func moveToWsBalEd(v decimal.Decimal) {
	WsBalEd = formatEdited("-Z,ZZZ,ZZ9.99", v)
}
func moveToWsTotEd(v decimal.Decimal) {
	WsTotEd = formatEdited("-ZZZ,ZZZ,ZZ9.99", v)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseAmt(raw string) decimal.Decimal {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return decimal.Zero
	}
	// digits only, 7 chars, may contain spaces? treat spaces as zeros?
	// Keep only digits
	digits := ""
	for _, c := range raw {
		if c >= '0' && c <= '9' {
			digits += string(c)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	n := decimal.RequireFromString(digits)
	// implied 2 decimals
	return n.Shift(-2)
}

